import{_ as s,o as e,c as i,a5 as a}from"./chunks/framework.DGp912Ge.js";const k=JSON.parse('{"title":"Sport Client (Joystick) — Python Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/python/sport-client-joy.md","filePath":"software/sdk/python/sport-client-joy.md","lastUpdated":1780296047000}'),o={name:"software/sdk/python/sport-client-joy.md"};function n(d,t,r,l,h,c){return e(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="sport-client-joystick-—-python-example" tabindex="-1">Sport Client (Joystick) — Python Example <a class="header-anchor" href="#sport-client-joystick-—-python-example" aria-label="Permalink to &quot;Sport Client (Joystick) — Python Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/python/example/sport/rbq_sport_client_joy.py</code></p><p>Python port of the C++ <a href="/RBQ/software/sdk/cpp/sport-client-joy.html"><code>rbq_sport_client_joy</code></a>.<br> Drives the robot using a <strong>gamepad / joystick</strong> via the Python <code>SportClient</code> API.<br> Analog sticks stream continuous <code>Move</code> velocity commands at <strong>10 Hz</strong>; buttons trigger discrete actions.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Unlike the C++ version&#39;s two-thread design, the Python example uses a <strong>single event loop</strong> at 10 Hz:</p><ol><li>Poll joystick events.</li><li>Check button chords → discrete action or analog-stick <code>Move</code>.</li><li>Call the matching <code>SportClient</code> method.</li><li>Sleep for the remainder of the 100 ms tick.</li></ol><p>This is simpler and sufficient for the 10 Hz control rate that the SportClient high-level interface operates at.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><code>rbq_sdk_py</code> installed — see <a href="/RBQ/software/sdk/python/overview.html">Python SDK Overview</a>.</li><li>A Linux joystick device at <code>/dev/input/js*</code>.</li><li>Robot stack running (simulation or hardware).</li></ul><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>From <code>rbq_sdk/python/example/sport/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_sport_client_joy.py</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">networkInterfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [joystickPath]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># auto-detect joystick:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_sport_client_joy.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># explicit joystick:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_sport_client_joy.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/input/js1</span></span></code></pre></div><p>Joystick auto-detection order:</p><ol><li><code>argv[2]</code> if given and readable.</li><li><code>$JOY</code> environment variable.</li><li>First <code>/dev/input/js*</code> device whose name matches <code>logitech</code>, <code>gamepad</code>, <code>x-box</code>, <code>xbox</code>, or <code>wireless</code>.</li><li>First available <code>/dev/input/js*</code> node.</li><li><code>/dev/input/js0</code> as a last resort.</li></ol><h2 id="gamepad-bindings" tabindex="-1">Gamepad bindings <a class="header-anchor" href="#gamepad-bindings" aria-label="Permalink to &quot;Gamepad bindings&quot;">​</a></h2><p>The mapping follows the <strong>Logitech F710 / Xbox layout</strong> on Linux.</p><h3 id="button-chords-checked-first" tabindex="-1">Button chords (checked first) <a class="header-anchor" href="#button-chords-checked-first" aria-label="Permalink to &quot;Button chords (checked first)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Buttons pressed</th><th>Action</th></tr></thead><tbody><tr><td><strong>L2 + B</strong></td><td><code>Damp</code> — emergency stop</td></tr><tr><td><strong>L2 + A</strong> <em>(1st press)</em></td><td><code>StandUp</code> — lock joints standing</td></tr><tr><td><strong>L2 + A</strong> <em>(2nd press)</em></td><td><code>StandDown</code> — go prone</td></tr><tr><td><strong>START</strong></td><td><code>SwitchGait(ID_DEFAULT_MODE)</code> — default gait</td></tr><tr><td><strong>L2 + START</strong></td><td><code>SwitchGait(ID_RUNNING_MODE)</code> — running mode</td></tr><tr><td><strong>L2 + X</strong></td><td><code>RecoveryStand</code></td></tr><tr><td><strong>R1 + X</strong></td><td><code>SwitchGait(ID_CLIMB_MODE)</code> — climb mode</td></tr><tr><td><strong>L1 + X</strong></td><td><strong>not supported on this robot</strong></td></tr><tr><td><strong>L1 + Y</strong></td><td><strong>not supported on this robot</strong></td></tr><tr><td><strong>BACK</strong></td><td><code>StopMove</code></td></tr></tbody></table><h3 id="double-click-bindings" tabindex="-1">Double-click bindings <a class="header-anchor" href="#double-click-bindings" aria-label="Permalink to &quot;Double-click bindings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Button</th><th>Window</th><th>Action</th></tr></thead><tbody><tr><td>Double <strong>X</strong></td><td>400 ms</td><td><code>LeftSideGait(1)</code></td></tr><tr><td>Double <strong>Y</strong></td><td>400 ms</td><td><code>RightSideGait(1)</code></td></tr><tr><td>Double <strong>R1</strong></td><td>400 ms</td><td><strong>not supported on this robot</strong></td></tr><tr><td>Double <strong>R2</strong> (trigger)</td><td>400 ms</td><td><strong>not supported on this robot</strong></td></tr></tbody></table><h3 id="analog-stick-velocity-when-no-button-is-pressed" tabindex="-1">Analog stick velocity (when no button is pressed) <a class="header-anchor" href="#analog-stick-velocity-when-no-button-is-pressed" aria-label="Permalink to &quot;Analog stick velocity (when no button is pressed)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Axis constant</th><th>Physical</th><th>Maps to</th><th>Max</th></tr></thead><tbody><tr><td><code>AXIS_LY</code> (1)</td><td>Left stick forward</td><td><code>vel_x</code></td><td>±1.0 m/s</td></tr><tr><td><code>AXIS_LX</code> (0)</td><td>Left stick left</td><td><code>vel_y</code></td><td>±0.5 m/s</td></tr><tr><td><code>AXIS_RX</code> (3)</td><td>Right stick left</td><td><code>vyaw</code></td><td>±1.0 rad/s</td></tr></tbody></table><p>Deadzone: <strong>0.12</strong> on all axes.</p><h2 id="axis-and-button-index-reference" tabindex="-1">Axis and button index reference <a class="header-anchor" href="#axis-and-button-index-reference" aria-label="Permalink to &quot;Axis and button index reference&quot;">​</a></h2><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">AXIS_LX</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">AXIS_LY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">AXIS_RX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">AXIS_LT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">AXIS_RT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">           =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # triggers; idle = -1, full press = +1</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PAD_A</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PAD_B</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PAD_X</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PAD_Y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PAD_LB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PAD_RB</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">             =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # L1, R1</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PAD_BACK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PAD_START</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span></span></code></pre></div><p>These match the standard <strong>Xbox / Logitech F710</strong> Linux <code>js*</code> mapping.<br> If buttons or axes appear swapped on your controller, check with <code>jstest /dev/input/js0</code>.</p><h2 id="key-implementation-notes" tabindex="-1">Key implementation notes <a class="header-anchor" href="#key-implementation-notes" aria-label="Permalink to &quot;Key implementation notes&quot;">​</a></h2><ul><li><strong><code>edge</code> detection</strong>: The <code>Joy</code> class stores <code>prev[]</code> and <code>edge[]</code> arrays. <code>edge[i]</code> is set to <code>True</code> only on a rising transition (button newly pressed, not held), and cleared by <code>end_frame()</code> at the end of each tick.</li><li><strong>R2 as virtual button</strong>: <code>r2_pressed = joy.ax[AXIS_RT] &gt; 0.0</code>; a rising edge <code>r2_edge</code> is computed manually and passed to <code>consume_double</code>.</li><li><strong><code>lock_toggle_to_prone</code></strong>: Alternates <code>StandUp</code> / <code>StandDown</code> on successive <code>L2+A</code> presses, matching the physical A2 controller behaviour.</li><li><strong>Error streak</strong>: Consecutive non-zero return codes increment <code>err_streak</code>; a warning is printed every 50 failures.</li></ul><h2 id="differences-from-the-c-version" tabindex="-1">Differences from the C++ version <a class="header-anchor" href="#differences-from-the-c-version" aria-label="Permalink to &quot;Differences from the C++ version&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>C++</th><th>Python</th></tr></thead><tbody><tr><td>Thread model</td><td>2 threads (joy + control)</td><td>Single loop at 10 Hz</td></tr><tr><td>Control rate</td><td>10 Hz</td><td>10 Hz</td></tr><tr><td>Double-click tracking</td><td><code>std::chrono::steady_clock</code></td><td><code>time.monotonic()</code></td></tr><tr><td>Joystick API</td><td><code>Joystick</code> C++ class</td><td>Self-contained <code>Joy</code> Python class (raw <code>fcntl</code>/<code>struct</code>)</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/RBQ/software/sdk/python/sport-client.html">Sport Client (Python)</a></li><li><a href="/RBQ/software/sdk/cpp/sport-client-joy.html">Sport Client Joystick (C++)</a></li><li><a href="/RBQ/software/sdk/python/overview.html">Python SDK Overview</a></li></ul>`,32)])])}const g=s(o,[["render",n]]);export{k as __pageData,g as default};
